"""Build accessible HTML fallbacks from the local CV and concert archive. No dependencies."""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).resolve().parent.parent
PUBLIC = ROOT / 'public'
CV = json.loads((PUBLIC / 'data/cv.json').read_text('utf-8'))
EVENTS = json.loads((PUBLIC / 'data/agenda.json').read_text('utf-8'))['events']
MEDIA = json.loads((PUBLIC / 'media/manifest.json').read_text('utf-8-sig'))
LANGS = ('es', 'en', 'fr', 'it')


def tr(*texts):
    return ''.join(f'<span lang="{lang}" data-lang="{lang}" class="inline-lang{" lang-active" if lang == "es" else ""}">{escape(text)}</span>' for lang, text in zip(LANGS, texts))


def image(item, alt, cls='', eager=False):
    return f'<img src="{item["src"]}" width="{item["width"]}" height="{item["height"]}" alt="{escape(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async"{" fetchpriority=high" if eager else ""}>'


def heading(label, *title):
    return f'<p class="eyebrow">{label}</p><h2>{tr(*title)}</h2>'


def event_item(event):
    return f'<li class="concert-item"><p class="concert-date">{escape(event["dateLabel"] or str(event.get("sortYear") or ""))}</p><div><p class="event-category">{tr("Dirección", "Conducting", "Direction", "Direzione") if event["category"] == "conducting" else tr("Órgano", "Organ", "Orgue", "Organo")}</p><h3 lang="es">{escape(event["title"])}</h3></div></li>'


def archive():
    groups = {}
    for event in sorted(EVENTS, key=lambda e: (e.get('date') or e.get('period') or str(e.get('sortYear') or '')), reverse=True):
        groups.setdefault(event.get('sortYear') or 'Sin fecha', []).append(event)
    return ''.join(f'<details class="archive-year"{" open" if year == 2026 else ""}><summary>{year}<span>{len(events)}</span></summary><ul class="concerts-list">{"".join(event_item(e) for e in events)}</ul></details>' for year, events in groups.items())


SECTION_NAMES = {
    'education': ('Formación académica', 'Education', 'Formation', 'Formazione'),
    'courses': ('Cursos y clases magistrales', 'Courses and masterclasses', 'Stages et masterclasses', 'Corsi e masterclass'),
    'appointments': ('Nombramientos y responsabilidades', 'Appointments and roles', 'Fonctions et responsabilités', 'Incarichi e responsabilità'),
    'awards': ('Premios y becas', 'Awards and scholarships', 'Prix et bourses', 'Premi e borse di studio'),
    'languages': ('Idiomas', 'Languages', 'Langues', 'Lingue'),
    'press': ('Prensa y publicaciones', 'Press and publications', 'Presse et publications', 'Stampa e pubblicazioni'),
}


def cv_details():
    return ''.join(f'<details class="cv-detail"><summary>{tr(*SECTION_NAMES[key])}</summary><ul lang="es">{"".join(f"<li>{escape(item)}</li>" for item in CV[key])}</ul></details>' for key in ['education', 'appointments', 'awards', 'courses', 'languages'])


